using System;using System.Linq;using Mono.Cecil;
class Publicize {static void Change(TypeDefinition t){if(t.IsNested){t.IsNestedPublic=true;}else t.IsPublic=true;foreach(var f in t.Fields){f.IsPublic=true;}foreach(var m in t.Methods){m.IsPublic=true;}foreach(var n in t.NestedTypes)Change(n);}static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(System.IO.Path.GetDirectoryName(args[0]));using(var m=ModuleDefinition.ReadModule(args[0],new ReaderParameters{AssemblyResolver=resolver})){foreach(var t in m.Types)Change(t);m.Write(args[1]);}}}
